/**
 * `src/lib/loginErrorFixtures.ts` is what `cargo test` would write. Issue #488 §4.
 *
 * # The gap this closes
 *
 * The fixture is generated by `login_error.rs`'s
 * `the_fixture_is_the_real_serialisation`, which is the authority and stays the
 * authority: it holds the Rust types and it is the only thing that writes the
 * file. But that test is reachable only through `cargo test`. #488 measured
 * what a contributor running `npm test` sees, and it is not the same board:
 *
 * - **Code drift** (`account_locked_or_expired` renamed) already reddens
 *   `tools/sign-in-test.mjs`, which compares the code sets in both directions.
 * - **Message drift** ("the account cannot sign in right now (LOCKED)" edited
 *   to anything at all) gave `76 checks passed, 0 failed`, exit 0. Only cargo
 *   saw it, and the fixture's messages are what the player reads.
 *
 * So a green `npm test` sat over a drifted message, and when the gate did go
 * red it went red in Rust - naming a Rust test for a file somebody had edited
 * in TypeScript. This is the TypeScript-side half, and it reddens naming the
 * TypeScript file.
 *
 * # What it can and cannot check, said plainly
 *
 * It does **not** re-implement the Rust `Display` impls in JavaScript. That
 * would be a second generator beside the real one and the two would drift,
 * which is the defect, not the fix (`CLAUDE.md` §0). Four properties instead,
 * every one of them derived from Rust source rather than typed here:
 *
 *   1. **The vocabulary.** `LoginCode`'s variants, `LoginCode::ALL` and
 *      `as_str`'s arms are three separate lists in `login_error.rs`. All three
 *      are parsed and asserted equal, N of N, and the snake_case string is
 *      derived from the variant name rather than trusted.
 *   2. **Both sides of the boundary.** That set, the fixture's codes in order,
 *      and the webview's own `RUST_ERROR_CODES` must be the same set. A code in
 *      one and not another is named.
 *   3. **The rendering.** The generated file's header is compared against the
 *      raw string literal inside `render_fixture`, byte for byte, and every
 *      entry line against the `format!` template beside it. So a hand-edited
 *      fixture is caught even where its *content* is unverifiable from here.
 *   4. **Message provenance.** Every fixture message must match a format-string
 *      literal that really exists in the Rust sources, with `{...}` holes
 *      treated as wildcards. That is what catches the drift cargo used to be
 *      alone in catching: an edited message matches nothing Rust can produce.
 *
 * What it cannot check is that the *values* in the holes are the ones Rust
 * would have put there - `(LOCKED)` could become `(BANNED)` and property 4
 * still passes. `cargo test` is the authority on that and remains so; this
 * says which half it covers rather than implying the whole.
 *
 * Regenerate with `DRC_WRITE_LOGIN_FIXTURE=1 cargo test login_error` in
 * `src-tauri`, then run the tests again *without* that variable - the
 * regenerating run deliberately fails (#488 §5).
 */
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const read = (rel) => readFileSync(join(root, rel), 'utf8').replace(/\r\n/g, '\n')

let pass = 0
let fail = 0
const ok = (name, cond, detail = '') => {
  if (cond) pass += 1
  else fail += 1
  console.log(`${cond ? 'OK  ' : 'FAIL'} ${name.padEnd(62)}${detail}`)
}

const RUST = 'src-tauri/src/login_error.rs'
const FIXTURE = 'src/lib/loginErrorFixtures.ts'
const rust = read(RUST)
const fixtureText = read(FIXTURE)

// ---------------------------------------------------------------------------
// 1. The vocabulary, from three independent lists in one Rust file.
// ---------------------------------------------------------------------------

/** `PascalCase` -> `snake_case`, the same rule `as_str` follows by hand. */
const snake = (v) => v.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase()

const enumBody = /pub enum LoginCode \{([\s\S]*?)\n\}/.exec(rust)?.[1] ?? ''
// Variant heads only: at the variant indent, capitalised, ending the line.
// Doc comments start with `/` and are not capitalised at that position.
const variants = [...enumBody.matchAll(/^ {4}([A-Z][A-Za-z0-9]*),$/gm)].map((m) => m[1])

const allBody = /pub const ALL: \[LoginCode; (\d+)\] = \[([\s\S]*?)\n {4}\];/.exec(rust)
const declaredLen = allBody ? Number(allBody[1]) : -1
const allMembers = allBody
  ? [...allBody[2].matchAll(/LoginCode::([A-Za-z0-9]+),/g)].map((m) => m[1])
  : []

const asStrBody = /pub fn as_str\(self\) -> &'static str \{([\s\S]*?)\n {4}\}/.exec(rust)?.[1] ?? ''
const asStrArms = [...asStrBody.matchAll(/LoginCode::([A-Za-z0-9]+) => "([a-z_]+)",/g)].map((m) => ({
  variant: m[1],
  code: m[2],
}))

// The denominators, first and loudly. Every comparison below is vacuously true
// against an empty parse, so a regex that stopped matching would otherwise
// report a perfectly consistent contract about nothing at all.
ok('the enum parser found variants', variants.length >= 10, `${variants.length}`)
ok('the ALL parser found members', allMembers.length >= 10, `${allMembers.length}`)
ok('the as_str parser found arms', asStrArms.length >= 10, `${asStrArms.length}`)

// A control on all three parsers at once: they must find nothing in a file that
// has none of these shapes, or "found N" above could be N from somewhere else.
const controlRust = 'pub enum Unrelated {\n    Thing,\n}\n'
ok(
  'control: the enum parser finds nothing in a file with no LoginCode',
  (/pub enum LoginCode \{([\s\S]*?)\n\}/.exec(controlRust)?.[1] ?? '') === '',
)

ok(
  'the declared ALL length is the number of members',
  declaredLen === allMembers.length,
  `declared ${declaredLen}, found ${allMembers.length}`,
)
ok(
  'ALL holds every enum variant, in enum order',
  JSON.stringify(allMembers) === JSON.stringify(variants),
  allMembers.join(', ') === variants.join(', ') ? `${variants.length} of ${variants.length}` : `ALL: ${allMembers.join(', ')} | enum: ${variants.join(', ')}`,
)
ok(
  'as_str covers every variant, in the same order',
  JSON.stringify(asStrArms.map((a) => a.variant)) === JSON.stringify(variants),
  asStrArms.map((a) => a.variant).join(', '),
)
const mistyped = asStrArms.filter((a) => a.code !== snake(a.variant))
ok(
  'every as_str string is the snake_case of its variant',
  mistyped.length === 0,
  mistyped.map((a) => `${a.variant} -> ${a.code}`).join(', ') || `${asStrArms.length} of ${asStrArms.length}`,
)

/** The one code vocabulary, derived from Rust and used for everything below. */
const rustCodes = asStrArms.map((a) => a.code)

// ---------------------------------------------------------------------------
// 2. Both sides of the boundary hold the same set.
// ---------------------------------------------------------------------------

const { LOGIN_ERROR_FIXTURES } = await import('../src/lib/loginErrorFixtures.ts')
const { RUST_ERROR_CODES, CODE_KINDS, LOGIN_ERROR_SENTENCES } = await import(
  '../src/lib/lichLogin.ts'
)

const fixtureCodes = LOGIN_ERROR_FIXTURES.map((f) => f.code)
ok('the generated fixture has entries', fixtureCodes.length >= 10, `${fixtureCodes.length}`)

ok(
  'the fixture holds one entry per Rust code, in LoginCode::ALL order',
  JSON.stringify(fixtureCodes) === JSON.stringify(rustCodes),
  fixtureCodes.length === rustCodes.length
    ? `${fixtureCodes.length} of ${rustCodes.length}`
    : `fixture: ${fixtureCodes.join(', ')} | rust: ${rustCodes.join(', ')}`,
)

const notDeclared = rustCodes.filter((c) => !RUST_ERROR_CODES.includes(c))
const noLongerSent = RUST_ERROR_CODES.filter((c) => !rustCodes.includes(c))
ok(
  'the webview declares exactly the codes Rust can send',
  notDeclared.length === 0 && noLongerSent.length === 0,
  `${RUST_ERROR_CODES.length} declared${notDeclared.length ? ` - not declared: ${notDeclared.join(', ')}` : ''}${noLongerSent.length ? ` - no longer sent: ${noLongerSent.join(', ')}` : ''}`,
)

// `internal` is the one code with no player sentence on purpose: there is no
// advice to give about a worker thread that did not finish, so it classifies to
// `unknown` and the raw message is printed. Named here rather than inferred, so
// a *second* code losing its sentence is a failure rather than a new normal.
const CODES_WITHOUT_A_SENTENCE = ['internal']
const unsentenced = rustCodes.filter(
  (c) => !CODE_KINDS[c] && !CODES_WITHOUT_A_SENTENCE.includes(c),
)
ok(
  'every Rust code but `internal` maps to a player sentence',
  unsentenced.length === 0,
  unsentenced.join(', ') || `${rustCodes.length - CODES_WITHOUT_A_SENTENCE.length} of ${rustCodes.length}`,
)
const danglingKinds = Object.entries(CODE_KINDS).filter(([, k]) => !LOGIN_ERROR_SENTENCES[k])
ok(
  'every kind those codes map to has a sentence',
  danglingKinds.length === 0,
  danglingKinds.map(([c, k]) => `${c}->${k}`).join(', '),
)

// ---------------------------------------------------------------------------
// 3. The rendering is the one `render_fixture` produces.
// ---------------------------------------------------------------------------

// The header is not retyped here: it is the `r#"..."#` literal in the Rust
// writer, read out of the source. A file whose banner has been edited - the
// "Generated. Do not edit." line most of all - is caught by this and by
// nothing else on the TypeScript side.
const header = /out\.push_str\(\s*r#"([\s\S]*?)"#,\s*\);/.exec(rust)?.[1] ?? ''
ok('the header literal was found in the Rust writer', header.length > 200, `${header.length} chars`)
ok(
  'the fixture file begins with exactly that header',
  header.length > 200 && fixtureText.startsWith(header),
  fixtureText.startsWith(header) ? 'byte for byte' : 'the checked-in banner differs from the writer',
)

// The entry format, likewise read from the writer rather than assumed.
const entryTemplate = /out\.push_str\(&format!\("(.*?)\\n"\)\);/.exec(rust)?.[1] ?? ''
ok(
  'the entry template was found in the Rust writer',
  entryTemplate.includes('{code}') && entryTemplate.includes('{message}'),
  entryTemplate,
)
// `{{`/`}}` are escaped braces in a Rust format string; `{code}`/`{message}` are
// serde_json strings, so each is a JSON string literal.
const entryRe = new RegExp(
  '^' +
    entryTemplate
      .replace(/[.*+?^$()|[\]\\]/g, '\\$&')
      .replace(/\{\{/g, '\\{')
      .replace(/\}\}/g, '\\}')
      .replace(/\{code\}/g, '("(?:[^"\\\\]|\\\\.)*")')
      .replace(/\{message\}/g, '("(?:[^"\\\\]|\\\\.)*")') +
    '$',
)
const bodyLines = fixtureText
  .split('\n')
  .filter((l) => l.startsWith('  { code:') || l.startsWith('  {code'))
ok(
  'every fixture entry is a line the writer could have produced',
  bodyLines.length === fixtureCodes.length && bodyLines.every((l) => entryRe.test(l)),
  `${bodyLines.filter((l) => entryRe.test(l)).length} of ${bodyLines.length} lines, ${fixtureCodes.length} entries`,
)
ok('the fixture ends the array and nothing follows it', fixtureText.endsWith('\n]\n'))

// ---------------------------------------------------------------------------
// 4. Message provenance: every message is a shape Rust can actually print.
// ---------------------------------------------------------------------------

/**
 * Every string literal in a Rust file, with line continuations joined.
 *
 * A `\` at the end of a line inside a Rust string swallows the newline *and*
 * the following indentation, which is how `eaccess.rs` wraps its longer
 * messages. Not joining them would leave a template that matches nothing and
 * report every long message as drifted - a check that always fires, which is
 * as empty as one that never does.
 */
function stringLiterals(source) {
  const out = []
  for (const m of source.matchAll(/"((?:[^"\\\n]|\\[\s\S])*)"/g)) {
    out.push(
      m[1]
        .replace(/\\\n\s*/g, '')
        .replace(/\\n/g, '\n')
        .replace(/\\"/g, '"')
        .replace(/\\\\/g, '\\'),
    )
  }
  return out
}

const RUST_MESSAGE_SOURCES = ['src-tauri/src/eaccess.rs', RUST, 'src-tauri/src/lich.rs']

/**
 * How much of a template has to be literal text before it is evidence of
 * anything.
 *
 * Found by running the control below: nine literals in these three files are
 * all hole and no text - `"{}"`, `"{err}"`, `"{}: {}"`, `"{host}:{port}"` -
 * and each of those matches every string in the universe. Left in, they would
 * have made "every message has provenance" the answer for any input at all,
 * which is a check that cannot fail. Twelve characters is comfortably below
 * the shortest real message here (`could not reach {endpoint}: {detail}`, 18)
 * and comfortably above every degenerate one (1).
 */
const MIN_LITERAL_CHARS = 12
const literalLength = (t) => t.replace(/\{[^{}]*\}/g, '').trim().length

const allLiterals = RUST_MESSAGE_SOURCES.flatMap((f) => stringLiterals(read(f)))
const templates = allLiterals.filter((t) => literalLength(t) >= MIN_LITERAL_CHARS)
ok(
  'the string-literal reader found templates',
  templates.length >= 100,
  `${templates.length} usable of ${allLiterals.length} from ${RUST_MESSAGE_SOURCES.length} files`,
)
ok(
  'and the all-hole templates that match everything were dropped',
  allLiterals.length - templates.length >= 5,
  `${allLiterals.length - templates.length} dropped`,
)

/** A Rust format template as a regexp, with `{...}` holes as wildcards. */
function templateMatches(template, message) {
  if (!template.includes('{')) return template === message
  const re = new RegExp(
    '^' +
      template
        .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
        .replace(/\\\{\\\{/g, '\\{')
        .replace(/\\\}\\\}/g, '\\}')
        .replace(/\\\{[^{}]*?\\\}/g, '[\\s\\S]*') +
      '$',
  )
  return re.test(message)
}

const unprovenanced = LOGIN_ERROR_FIXTURES.filter(
  (f) => !templates.some((t) => templateMatches(t, f.message)),
)
ok(
  'every fixture message matches a format string that exists in Rust',
  unprovenanced.length === 0,
  unprovenanced.map((f) => f.code).join(', ') ||
    `${LOGIN_ERROR_FIXTURES.length} of ${LOGIN_ERROR_FIXTURES.length}`,
)

// The control this check is worthless without. If a made-up sentence also
// matched something, "all messages have provenance" would be the answer for any
// input at all - and one of these templates really is a bare `{}`-only string
// somewhere, which would match everything if the guard above were dropped.
const NONSENSE = 'DRIFTED-SABOTAGE: this sentence is in no Rust source on this machine'
ok(
  'control: an invented message matches no Rust format string',
  !templates.some((t) => templateMatches(t, NONSENSE)),
)
// And the positive half: a real message with one hole filled differently still
// matches, so the check is about the shape and does not merely require the
// literal to be present verbatim.
ok(
  'control: a real template still matches with a different value in the hole',
  templates.some((t) =>
    templateMatches(t, 'the account cannot sign in right now (SOME-OTHER-TOKEN)'),
  ),
)

// ---------------------------------------------------------------------------
// 5. The writer cannot repair a drift and pass in the same run (#488 §5).
//
// A source-text check, and said so: the behaviour itself is Rust's and is
// proved by running `DRC_WRITE_LOGIN_FIXTURE=1 cargo test`, which fails. This
// exists so that removing the guard cannot be invisible to `npm test`.
// ---------------------------------------------------------------------------

const readsBeforeWriting =
  rust.indexOf('let before = std::fs::read_to_string(&path)') <
    rust.indexOf('std::fs::write(&path, &rendered)') &&
  rust.includes('does not pass on a fixture it repaired itself')
ok(
  'source: the Rust writer reads before it writes and fails after repairing',
  readsBeforeWriting,
)

// ---------------------------------------------------------------------------

console.log(`\n${pass} checks passed, ${fail} failed`)

// The denominator, derived rather than typed: a throw or an early return
// halfway down otherwise looks exactly like a clean pass.
const self = readFileSync(new URL(import.meta.url), 'utf8')
const declared = [...self.matchAll(/^ok\(|^\s{0,2}ok\(/gm)].length
const ran = pass + fail
if (ran < declared) {
  console.log(`FAIL only ${ran} of an expected ${declared} assertions ran - the rest never executed`)
  process.exit(1)
}
console.log(`   ${ran} assertions ran (expected at least ${declared})`)
process.exit(fail === 0 ? 0 : 1)
